// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }

    function testFuzz_property(uint256 v) public {
        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }

        c.SetMinSum(v);
        try c.SetMinSum(v) {
            ok = ok && true;
        } catch {
            ok = false;
        }

        assertTrue(c.MinSum() == v);
    }
}
